def _safe_float(val: str | None, default: float | None = None) -> float | None:
    if val is None or val == "" or val == "N/A":
        return default
    try:
        v = float(val)
        if v in (-3.0, -4.0):
            return default
        return v
    except (ValueError, TypeError):
        return default

